CREATE VIEW Vue_TrsRec AS  
SELECT 'GRN' AS TrsType, Trs_Grn1.Coycode, 0 AS DcNo,'' as clos , '' AS DcFinyear, Trs_Grn1.DocNo AS GrnNo, Trs_Grn1.Finyear, Trs_Grn1.dt AS GrnDate, Trs_GRN2.ordid, Mas_Party.Pname, Mas_Party.PID, Trs_Grn1.PartyDCref, Mas_Dept.Deptname, Mas_Dept.DeptID, Trs_GRN2.StockID, Trs_GRN2.RBag, Trs_GRN2.RecKgs, Trs_GRN2.Recmtr, '' AS ProcessType,'N' as MultiGRN, isNull(Trs_Grn1.SubPrsId,0) as SubPrsID FROM Trs_Grn1 INNER JOIN Trs_GRN2 ON Trs_Grn1.ID = Trs_GRN2.ID INNER JOIN Mas_Party ON Trs_Grn1.SuppID = Mas_Party.PID INNER JOIN Mas_Dept  ON Trs_Grn1.Dept = Mas_Dept.DeptID WHERE (Trs_Grn1.GRNType IN ('Purchase'))

 UNION ALL /*Comment Break*/ SELECT 'GRN' AS TrsType, Trs_Grn1_4.Coycode, 0 AS DcNo, '' as clos, '' AS DcFinyear, Trs_Grn1_4.DocNo AS GrnNo, Trs_Grn1_4.Finyear, Trs_Grn1_4.dt AS GrnDate,Trs_GRN2_4.ordid, Mas_Party_4.Pname, Mas_Party_4.PID, Trs_Grn1_4.PartyDCref, Mas_Dept_6.Deptname, Mas_Dept_6.DeptID, Trs_GRN2_4.StockID, Trs_GRN2_4.RBag, Trs_GRN2_4.RecKgs, Trs_GRN2_4.Recmtr, '' AS ProcessType,'N' as MultiGRN, isNull(Trs_Grn1_4.SubPrsId,0) as SubPrsID FROM Trs_Grn1 AS Trs_Grn1_4 INNER JOIN Trs_GRN2 AS Trs_GRN2_4 ON Trs_Grn1_4.ID = Trs_GRN2_4.ID INNER JOIN Mas_Party AS  Mas_Party_4 ON Trs_Grn1_4.SuppID = Mas_Party_4.PID INNER JOIN Mas_Dept AS Mas_Dept_6 ON Trs_Grn1_4.Dept = Mas_Dept_6.DeptID WHERE (Trs_Grn1_4.GRNType IN ('Acc.Purch'))  UNION ALL /*Comment Break*/ SELECT 'PRSREC' AS TrsType, Trs_Grn1_3.Coycode, Trs_Del1.DocNo,Trs_Del1 .Clos , Trs_Del1.Finyear, Trs_Grn1_3.DocNo AS GrnNo, Trs_Grn1_3.Finyear, Trs_Grn1_3.dt AS GrnDate,Trs_GRN2_3.ordid, Mas_Party_3.Pname, Mas_Party_3.PID, Trs_Grn1_3.PartyDCref, Mas_Dept_5.Deptname, Mas_Dept_5.DeptID, Trs_GRN2_3.StockID, Trs_GRN2_3.RBag, Trs_GRN2_3.RecKgs,Trs_GRN2_3.Recmtr, Trs_Grn1_3.ProcessType AS ProcessType,'N' as MultiGRN, isNull(Trs_Grn1_3.SubPrsId,0) as SubPrsID FROM Trs_Grn1 AS Trs_Grn1_3 INNER JOIN Trs_GRN2 AS Trs_GRN2_3 ON Trs_Grn1_3.ID = Trs_GRN2_3.ID INNER JOIN  Mas_Party AS Mas_Party_3 ON Trs_Grn1_3.SuppID = Mas_Party_3.PID INNER JOIN Mas_Dept AS Mas_Dept_5 ON Trs_Grn1_3.Dept = Mas_Dept_5.DeptID LEFT OUTER JOIN Trs_Del1 ON  Trs_Grn1_3.DCID = Trs_Del1.ID WHERE (Trs_Grn1_3.GRNType IN ('Process', 'Acc.Proc.Receipt', 'DirectReceipt', 'Acc.Direct'))  UNION ALL /* Dyeing DC Made in Normal Entry -> But Dyeing GRN Made in Indirect GRN Entry (MultiPrsGRN) */ SELECT 'PRSREC' AS TrsType, Trs_Grn1_3.Coycode, Trs_Del1.DocNo,trs_del1.clos , Trs_Del1.Finyear, Rtrim(Trs_Grn1_3.DocNo) AS GrnNo, Trs_Grn1_3.Finyear, Trs_Grn1_3.Grndate AS GrnDate, Trs_MultiPrs_Grn3.ordid, Mas_Party_3.Pname, Mas_Party_3.PID, Trs_Grn2_3.PartyDCref, Mas_Dept_5.Deptname, Mas_Dept_5.DeptID,
 Trs_MultiPrs_Grn3.StockID, Trs_MultiPrs_Grn3.RBag, Trs_MultiPrs_Grn3.RecKgs, Trs_MultiPrs_Grn3.Recmtr, Trs_Grn1_3.ProcessType AS ProcessType,'Y' as MultiGRN , isNull(Trs_GRN2_3.SubPrsId,0) as SubPrsID FROM Trs_MultiPrs_Grn1 AS Trs_Grn1_3 INNER JOIN Trs_MultiPrs_Grn2 AS Trs_GRN2_3 ON Trs_Grn1_3.ID
 = Trs_GRN2_3.ID INNER JOIN Trs_MultiPrs_Grn3 ON Trs_Grn1_3.ID = Trs_MultiPrs_Grn3.ID and Trs_Grn2_3.DeptID = Trs_MultiPrs_Grn3.DeptID INNER JOIN Mas_Party AS Mas_Party_3 ON Trs_Grn2_3.PartyID = Mas_Party_3.PID INNER JOIN Mas_Dept AS Mas_Dept_5 ON Trs_Grn2_3.DeptID = Mas_Dept_5.DeptID INNER JOIN Trs_Del1 ON Trs_Grn2_3.OurDCID = Trs_Del1.ID WHERE (Trs_Grn1_3.GRNType IN ('Process', 'Acc.Proc.Receipt', 'DirectReceipt', 'Acc.Direct')) and Trs_Grn2_3.OurDCID <> 0 UNION ALL /* DC Made in Indirct Entry -> And GRN Made in Indirect Entry (MultiPrsGRN) */ SELECT 'PRSREC' AS TrsType, Trs_Grn1_3.Coycode, Trs_Grn1_3.DocNo, Dcclose as clos, Trs_Grn1_3.Finyear, Trs_Grn1_3.DocNo AS GrnNo, Trs_Grn1_3.Finyear, Trs_Grn1_3.Grndate AS GrnDate, Trs_MultiPrs_Grn3.ordid, Mas_Party_3.Pname, Mas_Party_3.PID, Trs_Grn2_3.PartyDCref, Mas_Dept_5.Deptname, Mas_Dept_5.DeptID, Trs_MultiPrs_Grn3.StockID, Trs_MultiPrs_Grn3.RBag, Trs_MultiPrs_Grn3.RecKgs, Trs_MultiPrs_Grn3.Recmtr, Trs_Grn1_3.ProcessType AS ProcessType,'Y' as MultiGRN, isNull(Trs_GRN2_3.SubPrsId,0) as SubPrsID FROM Trs_MultiPrs_Grn1 AS Trs_Grn1_3 INNER JOIN Trs_MultiPrs_Grn2 AS Trs_GRN2_3 ON Trs_Grn1_3.ID = Trs_GRN2_3.ID INNER JOIN Trs_MultiPrs_Grn3 ON Trs_Grn1_3.ID = Trs_MultiPrs_Grn3.ID and Trs_Grn2_3.DeptID = Trs_MultiPrs_Grn3.DeptID INNER JOIN Mas_Party AS Mas_Party_3 ON  Trs_Grn2_3.PartyID = Mas_Party_3.PID INNER JOIN Mas_Dept AS Mas_Dept_5 ON Trs_Grn2_3.DeptID = Mas_Dept_5.DeptID WHERE (Trs_Grn1_3.GRNType IN ('Process', 'Acc.Proc.Receipt', 'DirectReceipt', 'Acc.Direct')) and Trs_Grn2_3.OurDCID = 0 and IsNull(Trs_GRN2_3.FinalProcess,'N') = 'N' UNION ALL /*Comment Break*/ SELECT 'PRSRET' AS TrsType, Trs_Grn1_2.Coycode, Trs_Del1_2.DocNo,Trs_Del1_2.clos , Trs_Del1_2.Finyear, Trs_Grn1_2.DocNo AS GrnNo, Trs_Grn1_2.Finyear,  Trs_Grn1_2.dt AS GrnDate, Trs_GRN2_2.ordid, Mas_Party_2.Pname, Mas_Party_2.PID, Trs_Grn1_2.PartyDCref, Mas_Dept_4.Deptname, Mas_Dept_4.DeptID, Trs_GRN2_2.StockID,  Trs_GRN2_2.RBag, Trs_GRN2_2.RecKgs, Trs_GRN2_2.Recmtr, '' AS ProcessType,'N' as MultiGRN, isNull(Trs_Grn1_2.SubPrsId,0) as SubPrsID FROM Trs_Grn1 AS Trs_Grn1_2 INNER JOIN Trs_GRN2 AS Trs_GRN2_2 ON Trs_Grn1_2.ID =  Trs_GRN2_2.ID INNER JOIN Mas_Party AS Mas_Party_2 ON Trs_Grn1_2.SuppID = Mas_Party_2.PID INNER JOIN Mas_Dept AS Mas_Dept_4 ON Trs_Grn1_2.Dept = Mas_Dept_4.DeptID LEFT OUTER JOIN  Trs_Del1 AS Trs_Del1_2 ON Trs_Grn1_2.DCID = Trs_Del1_2.ID WHERE (Trs_Grn1_2.GRNType IN ('Process Return','Acc.Proc.Return', 'Acc.Iss.Ret'))   UNION ALL /*Comment Break*/ SELECT 'Opn' AS TrsType, Trs_Opening.Coycode, 0 AS DcNo,'' as clos, '' AS Dcfinyear, 0 AS Grnno, Trs_Opening.Finyear, Trs_Opening.OpenDt, Trs_Opening.OrdID,'OPENING ITEMS' AS Expr1, 0 AS Pid, '' AS Partydcref, Mas_Dept_3.Deptname, Trs_Opening.Dept, Trs_Opening.StockID,Trs_Opening.RlsBg, Trs_Opening.Kgs, Trs_Opening.MtrPc, '' AS ProcessType ,'N' as MultiGRN, isNull(Trs_Opening.SubPrsId,0) as SubPrsID FROM Trs_Opening INNER JOIN Mas_Dept AS Mas_Dept_3 ON Trs_Opening.Dept = Mas_Dept_3.DeptID  UNION ALL /*Comment Break*/ SELECT 'TRANS' AS TrType, isnull(Trs_Del1_1.ToCoycode, Trs_Del1_1.Coycode), Trs_Del1_1.DocNo AS DcNo, Trs_Del1_1.Clos , Trs_Del1_1.Finyear AS DcFinyear, Trs_Del1_1.DocNo AS GrnNo, Trs_Del1_1.Finyear, Trs_Del1_1.Dt AS DcDate, Trs_Del2.TranOrdID, 'TRANSFER IN ' + case OrderMas.Jobno when 0 then 'GENERAL/' +Ordermas.finyear+'->'+ OrderMas.BuyOrdNo else RTRIM(CAST(OrderMas.Jobno AS varchar))+ '/' +Ordermas.finyear+'->'+ OrderMas.BuyOrdNo end  AS BuyerOrdNo, 0 AS Expr2, '' AS Expr3, Mas_Dept_2.Deptname, Mas_Dept_2.DeptID, Trs_Del2.TranID, Trs_Del2.BgRl, Trs_Del2.Kg, Trs_Del2.mtr, Trs_Del1_1.ProcessType,'N' as MultiGRN, isNull(Trs_Del1_1.SubPrsId,0) as SubPrsID FROM Trs_Del1 AS Trs_Del1_1 INNER JOIN Trs_Del2 ON Trs_Del1_1.ID = Trs_Del2.ID INNER JOIN Mas_Dept AS Mas_Dept_2 ON Trs_Del1_1.Prs_Dept = Mas_Dept_2.DeptID INNER JOIN OrderMas ON Trs_Del2.OrdId = OrderMas.OrdId WHERE (Trs_Del1_1.TrType IN (3, 8))UNION ALL /*Comment Break*/ SELECT 'SALES RET' AS TrsType, Trs_Grn1_1.Coycode, 0 AS DcNo, '' as clos, '' AS DcFinyear, Trs_Grn1_1.DocNo AS GrnNo, Trs_Grn1_1.Finyear,  Trs_Grn1_1.dt AS GrnDate, Trs_GRN2_1.ordid, 'SALES RET - ' + case when trs_grn1_1.suppid=0 then Mas_buyer_1.buyername else  Mas_Party_1.Pname end AS Expr1,  case when trs_grn1_1.suppid=0 then Mas_buyer_1.buyerid else Mas_Party_1.PID end as PID , Trs_Grn1_1.PartyDCref, Mas_Dept_1.Deptname, Mas_Dept_1.DeptID, Trs_GRN2_1.StockID, Trs_GRN2_1.RBag, Trs_GRN2_1.RecKgs, Trs_GRN2_1.Recmtr, '' AS ProcessType,'N' as MultiGRN, isNull(Trs_Grn1_1.SubPrsId,0) as SubPrsID FROM Trs_Grn1 AS Trs_Grn1_1 INNER JOIN Trs_GRN2 AS Trs_GRN2_1 ON Trs_Grn1_1.ID = Trs_GRN2_1.ID left outer JOIN Mas_Party AS Mas_Party_1 ON Trs_Grn1_1.SuppID = Mas_Party_1.PID INNER JOIN StockTable ON Trs_GRN2_1.StockID = StockTable.StockID INNER JOIN  Mas_Dept AS Mas_Dept_1 ON StockTable.Dept = Mas_Dept_1.DeptID  left outer join MAs_buyer MAs_buyer_1 on trs_grn1_1 .buyer= MAs_buyer_1.buyerid WHERE (Trs_Grn1_1.GRNType ='Sales Return') Union All /* Comment Break */ SELECT     'Cutting ACk'TrType, Trs_CutApr.Coycode, Trs_Del1.DocNo As DcNo,Trs_Del1.clos, Trs_Del1.Finyear As DcFinyear, Trs_CutApr.AprNo As GrnNo, Trs_CutApr.Finyear , Trs_CutApr.AprDt As GrnDate, Trs_Del2.OrdId,case  when Trs_CutApr.Coycode=Trs_Del1.Coycode then  Mas_Exporter.ExporterName else  Mas_Exporter.ExporterName+'('+Unit.ExporterName+')' end As Pname, Trs_Del1.Coycode AS Pid,'' As PartyDCref, Mas_Dept.Deptname, Mas_Dept.DeptID, Trs_Del2.StockID,Trs_Del2.Arl As Rbags, Trs_Del2.AKg As RKgs, Trs_Del2.AMtr, Trs_Del1.ProcessType,'N' as MultiGRN, isNull(Trs_Del1.SubPrsId,0) as SubPrsID FROM Trs_Del2 INNER JOIN Trs_Del1 ON Trs_Del2.ID = Trs_Del1.ID INNER JOIN Trs_CutApr ON Trs_Del1.PrdID = Trs_CutApr.ID INNER JOIN Mas_Exporter ON Trs_Del1.Coycode = Mas_Exporter.ExpID INNER JOIN Mas_Dept ON Trs_Del1.Prs_Dept = Mas_Dept.DeptID INNER JOIN Mas_Exporter AS Unit ON Trs_CutApr.Coycode = Unit.ExpID where Isnull(Arl,0)>0  Or Isnull(AKg,0)>0 Or Isnull(AMtr,0)>0 